-- =============================================================================
-- 455 — LE CAHIER D'EXERCICES DE TLE (partie 20)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 455 --niveau Tle --matieres chimie-biologie-physiopathologie,sciences-sanitaires-sociales --suffixe 20 > supabase/contenu/455_exercices_tle_20.sql
--
-- 96 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   chimie-biologie-physiopathologie.k142  24 exercices · 8 chapitres
--   chimie-biologie-physiopathologie.k143  24 exercices · 8 chapitres
--   sciences-sanitaires-sociales.k189  24 exercices · 8 chapitres
--   sciences-sanitaires-sociales.k190  24 exercices · 8 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('187144dd-5550-51c0-9858-de1b06adec58'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le trajet de l’ovocyte","competence":"observer-schema","situation":"Sur une planche d’anatomie, l’appareil génital féminin est dessiné de face, sans légende. À toi de reconnaître les organes.","documents":[{"id":"app","type":"schema","titre":"Appareil génital féminin, vu de face","largeur":340,"hauteur":250,"elements":[{"teinte":"rose","motif":"clair","zone":true,"forme":"polygone","points":[[130,80],[210,80],[196,150],[180,196],[160,196],[144,150]],"id":"z1"},{"teinte":"rose","motif":"clair","zone":true,"forme":"rect","x":160,"y":196,"l":20,"h":28,"arrondi":4,"id":"z2"},{"teinte":"rose","motif":"clair","zone":true,"forme":"rect","x":62,"y":74,"l":70,"h":12,"arrondi":6,"id":"z3"},{"teinte":"rose","motif":"clair","zone":true,"forme":"rect","x":208,"y":74,"l":70,"h":12,"arrondi":6,"id":"z4"},{"teinte":"rose","motif":"clair","zone":true,"forme":"cercle","cx":56,"cy":80,"r":13,"id":"z5"},{"teinte":"rose","motif":"clair","zone":true,"forme":"cercle","cx":284,"cy":80,"r":13,"id":"z6"},{"teinte":"rose","motif":"clair","zone":true,"forme":"ellipse","cx":52,"cy":120,"rx":24,"ry":17,"id":"z7"},{"teinte":"rose","motif":"clair","zone":true,"forme":"ellipse","cx":288,"cy":120,"rx":24,"ry":17,"id":"z8"},{"forme":"texte","x":170,"y":242,"texte":"Schéma simplifié, sans échelle","taille":"petit","ancre":"milieu","italique":true}]}],"questions":[{"enonce":"Touche les deux ovaires.","aide":"Ce sont les deux organes en forme d’ovale, placés de part et d’autre de l’utérus, tout au bout des trompes.","type":"zone","document":"app","multiple":true},{"enonce":"Touche l’organe dans lequel l’embryon s’implante.","aide":"C’est le gros organe central, en forme de poire renversée, dont la muqueuse s’épaissit à chaque cycle.","type":"zone","document":"app","multiple":false},{"enonce":"Range les lieux par lesquels passent l’ovocyte II puis la cellule-œuf, de l’ovulation jusqu’à la nidation.","aide":"L’ovocyte II est libéré par l’ovaire, puis capté par le bord de la trompe ; la fécondation a lieu dans la partie externe de la trompe.","type":"ordre","items":[{"id":"a","texte":"Ampoule de la trompe (fécondation)"},{"id":"b","texte":"Utérus (nidation)"},{"id":"c","texte":"Pavillon de la trompe"},{"id":"d","texte":"Ovaire (ovulation)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z7","z8"]},"explication":"Les **ovaires** produisent les ovocytes et les hormones sexuelles féminines (œstrogènes et progestérone)."},{"cle":{"type":"zone","ids":["z1"]},"explication":"La nidation se fait dans l’endomètre, la muqueuse de l’**utérus**."},{"cle":{"type":"ordre","ids":["d","c","a","b"]},"explication":"Dans l’ordre : **ovaire, pavillon, ampoule de la trompe, utérus**. L’ovocyte est capté par le pavillon, la fécondation a lieu dans l’ampoule, puis la cellule-œuf migre vers l’utérus."}]$ex$::jsonb),
  ('187144dd-5550-51c0-9858-de1b06adec58'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Combien de chromosomes ?","competence":"lire-tableau","situation":"Un laboratoire compare les stades de la formation des gamètes chez l’homme et chez la femme. La case violette est à compléter.","documents":[{"id":"gam","type":"tableau","titre":"Les stades de la gamétogenèse","colonnes":["Cellule","Sexe","Chromosomes"],"lignes":[["Spermatogonie","Homme","46"],["Spermatocyte I","Homme","46"],["Spermatocyte II","Homme","?"],["Spermatozoïde","Homme","23"],["Ovocyte I","Femme","46"],["Ovocyte II","Femme","23"]],"enteteLignes":true,"source":"Valeurs du cours"}],"questions":[{"enonce":"Complète la case violette : combien de chromosomes contient un spermatocyte II ?","aide":"Compare avec le spermatozoïde : la méiose a déjà réduit le nombre de chromosomes.","type":"nombre"},{"enonce":"Range ces cellules selon leur nombre de chromosomes.","aide":"Les gonies et les cellules de stade I sont diploïdes ; les cellules de stade II et les gamètes ont subi la méiose.","type":"categories","categories":[{"id":"c0","texte":"2n = 46"},{"id":"c1","texte":"n = 23"}],"items":[{"id":"i0","texte":"Spermatogonie"},{"id":"i1","texte":"Ovocyte I"},{"id":"i2","texte":"Spermatozoïde"},{"id":"i3","texte":"Ovogonie"},{"id":"i4","texte":"Ovocyte II"},{"id":"i5","texte":"Spermatide"}]},{"enonce":"À l’ovulation, l’ovocyte II est libéré, mais sa méiose est bloquée. Qu’est-ce qui lui permet de l’achever ?","aide":"Relis la ligne « Ovogenèse » du cours : la méiose ne s’achève que dans un cas précis.","type":"choix","options":[{"id":"a","texte":"La rupture du follicule mûr sous l’effet d’un pic de LH"},{"id":"b","texte":"La fécondation par un spermatozoïde qui entre dans l’ovocyte"},{"id":"c","texte":"La sécrétion de progestérone par le corps jaune de l’ovaire"},{"id":"d","texte":"Le passage de l’ovocyte dans la cavité de l’utérus, après la trompe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":23,"tolerance":0},"affichage":"23","explication":"Un spermatocyte II est **haploïde (n = 23)** : la première division de méiose a déjà séparé les deux chromosomes de chaque paire."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c1"}},"explication":"Ovogonie, spermatogonie et ovocyte I sont **diploïdes (2n = 46)**. Spermatide, ovocyte II et spermatozoïde sont **haploïdes (n = 23)**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Sans fécondation, l’ovocyte II dégénère. C’est **la fécondation** qui débloque la fin de la méiose : la cellule-œuf obtenue est diploïde (2n = 46)."}]$ex$::jsonb),
  ('187144dd-5550-51c0-9858-de1b06adec58'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le carnet de suivi de Léa","competence":"analyser-document","situation":"Léa attend un bébé. Son médecin date la grossesse en semaines d’aménorrhée (SA), comptées depuis le premier jour des dernières règles. Voici son carnet.","documents":[{"id":"carnet","type":"tableau","titre":"Carnet de suivi (dates imaginées)","colonnes":["Événement","Date"],"lignes":[["Premier jour des dernières règles","1er mars"],["Prise de sang pour les sérologies","26 avril"],["Échographie de datation","à 12 SA"]],"enteteLignes":true,"source":"Exemple imaginé pour l’exercice"},{"id":"sero","type":"tableau","titre":"Résultats de la prise de sang","colonnes":["Maladie","Anticorps recherchés","Résultat"],"lignes":[["Toxoplasmose","IgG","Négatif"],["Rubéole","IgG","Positif"]],"enteteLignes":true,"source":"Résultats imaginés pour l’exercice"}],"questions":[{"enonce":"Le jour de la prise de sang, à combien de SA Léa en est-elle (en semaines entières) ? Mars compte 31 jours.","aide":"Compte les jours du 1er mars au 26 avril, puis divise par 7.","type":"nombre","unite":"SA"},{"enonce":"L’échographie de datation est prévue à 12 SA, soit 84 jours après le 1er mars. Quel jour de mai a-t-elle lieu ? Mars compte 31 jours et avril 30.","aide":"Du 1er mars au 1er mai, il y a 61 jours ; combien en reste-t-il jusqu’à 84 ?","type":"nombre","unite":"mai"},{"enonce":"Touche le résultat qui montre que Léa n’a pas d’anticorps contre la toxoplasmose.","aide":"Cherche la ligne « Toxoplasmose », puis la colonne des résultats.","type":"zone","document":"sero","multiple":false},{"enonce":"Quelle conduite de prévention correspond à la situation de Léa pour la toxoplasmose ?","aide":"Un résultat négatif ne protège pas : que recommande le cours à une femme enceinte non immunisée ?","type":"choix","options":[{"id":"a","texte":"Faire une amniocentèse tout de suite pour chercher le parasite"},{"id":"b","texte":"Cuire la viande, laver les crudités et refaire la sérologie chaque mois"},{"id":"c","texte":"Arrêter tous les contrôles, car le résultat est rassurant pour toujours"},{"id":"d","texte":"Ne rien changer, car ce résultat prouve que Léa est protégée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 SA","explication":"Du 1er mars au 26 avril, il s’écoule 56 jours : 56 ÷ 7 = **8 SA**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24 mai","explication":"Le 1er mars + 84 jours : 61 jours mènent au 1er mai, il reste 23 jours, donc le **24 mai**."},{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Un résultat **négatif** aux IgG signifie que Léa n’a jamais rencontré le parasite : elle n’est pas protégée."},{"cle":{"type":"choix","ids":["b"]},"explication":"Non immunisée, Léa doit éviter toute contamination (**viande bien cuite, crudités lavées, pas de litière de chat**) et refaire une sérologie **chaque mois**."}]$ex$::jsonb),
  ('31ca182d-6662-5a01-9334-b6966de2a089'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les hormones d’un cycle","competence":"lire-graphique","situation":"Un cycle dure 28 jours. Le graphique donne, de trois jours en trois jours, les taux de deux hormones ovariennes (courbes schématiques).","documents":[{"id":"cyc","type":"graphique","forme":"courbe","titre":"Taux hormonaux au cours d’un cycle","categories":["J2","J5","J8","J11","J14","J17","J20","J23","J26"],"series":[{"nom":"Œstrogènes","valeurs":[20,30,50,80,100,60,80,75,40],"teinte":"corail"},{"nom":"Progestérone","valeurs":[5,5,5,5,10,40,90,100,40],"teinte":"bleu"}],"axeY":{"titre":"Concentration","unite":"unités arbitraires","min":0,"max":100,"pas":20},"axeX":{"titre":"Jour du cycle"},"valeurs":false,"source":"Courbes schématiques"}],"questions":[{"enonce":"Touche le jour où le taux d’œstrogènes est le plus élevé.","aide":"Cherche le sommet de la courbe des œstrogènes.","type":"zone","document":"cyc","multiple":false},{"enonce":"De combien d’unités le taux de progestérone augmente-t-il entre J14 et J20 ?","aide":"Lis la valeur à J14 et celle à J20, puis soustrais.","type":"nombre","unite":"unités"},{"enonce":"Entre J15 et J28, quelle structure de l’ovaire sécrète ces deux hormones ?","aide":"Après l’ovulation, que devient le follicule qui s’est rompu ?","type":"choix","options":[{"id":"a","texte":"Le follicule mûr, juste avant l’ovulation"},{"id":"b","texte":"Le corps jaune, issu du follicule rompu"},{"id":"c","texte":"L’ovocyte II, libéré dans la trompe"},{"id":"d","texte":"L’endomètre, épaissi dans l’utérus"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"Le pic d’**œstrogènes** a lieu vers **J14**. Il déclenche le pic de LH, puis l’ovulation."},{"cle":{"type":"nombre","valeur":80,"tolerance":0},"affichage":"80 unités","explication":"À J14 : 10 ; à J20 : 90. La progestérone augmente de 90 − 10 = **80 unités**."},{"cle":{"type":"choix","ids":["b"]},"explication":"La phase lutéale est dominée par le **corps jaune**, qui sécrète progestérone et œstrogènes ; l’endomètre, lui, est une cible de ces hormones."}]$ex$::jsonb),
  ('31ca182d-6662-5a01-9334-b6966de2a089'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Un traitement à la testostérone","competence":"analyser-document","situation":"Dans une étude fictive, un homme adulte reçoit pendant trois mois de la testostérone en injections. Le schéma résume le contrôle de sa production naturelle ; le tableau donne ses dosages sanguins.","documents":[{"id":"boucle","type":"chaine","disposition":"cycle","noeuds":[{"id":"z1","texte":"Hypothalamus"},{"id":"z2","texte":"Hypophyse"},{"id":"z3","texte":"Testicules"},{"id":"z4","texte":"Testostérone dans le sang"}],"liens":[{"de":"z1","a":"z2","texte":"GnRH"},{"de":"z2","a":"z3","texte":"LH et FSH"},{"de":"z3","a":"z4","texte":"sécrètent"},{"de":"z4","a":"z1","texte":"freine"}]},{"id":"dosages","type":"tableau","titre":"Dosages sanguins","colonnes":["Dosage","Avant","Après 3 mois"],"lignes":[["Testostérone (nmol/L)","15","40"],["LH (UI/L)","6","1,5"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche l’organe qui fabrique la testostérone.","aide":"Les gonades masculines sont les seules à la fabriquer.","type":"zone","document":"boucle","multiple":false},{"enonce":"Par quel nombre la concentration de LH a-t-elle été divisée entre « Avant » et « Après 3 mois » ?","aide":"Divise la valeur « Avant » par la valeur « Après ».","type":"nombre"},{"enonce":"Pourquoi la LH baisse-t-elle alors que la testostérone injectée augmente dans le sang ?","aide":"Regarde la flèche « freine » sur le schéma.","type":"choix","options":[{"id":"a","texte":"Plus de testostérone stimule l’hypophyse, qui sécrète donc davantage de LH"},{"id":"b","texte":"Plus de testostérone est détectée par les testicules, qui fabriquent alors de la LH"},{"id":"c","texte":"Plus de testostérone freine l’hypothalamus et l’hypophyse, donc elles sécrètent moins de LH"},{"id":"d","texte":"Plus de testostérone détruit l’hypophyse, qui ne sécrète donc plus aucune hormone"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La testostérone est sécrétée par les **testicules**, sous la commande de la LH."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"6 ÷ 1,5 = **4** : la LH est quatre fois plus faible."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est un **rétrocontrôle négatif** : la testostérone (naturelle ou injectée) freine l’hypothalamus et l’hypophyse, donc la LH diminue."}]$ex$::jsonb),
  ('31ca182d-6662-5a01-9334-b6966de2a089'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un couple consulte","competence":"raisonner","situation":"Après 18 mois sans grossesse, un couple passe des examens. Le médecin doit choisir parmi plusieurs techniques d’aide médicale à la procréation.","documents":[{"id":"bilan","type":"tableau","titre":"Bilan du couple","colonnes":["Examen","Résultat"],"lignes":[["Durée sans grossesse malgré des rapports réguliers","18 mois"],["Ovulation de Mme (dosages hormonaux)","Normale"],["Trompes de Mme (radiographie)","Les deux sont obstruées"],["Spermogramme de M.","Normal"]],"enteteLignes":true,"source":"Cas imaginé pour l’exercice"},{"id":"techs","type":"tableau","titre":"Les techniques d’AMP","colonnes":["Technique","Principe"],"lignes":[["Stimulation ovarienne","Médicaments qui déclenchent l’ovulation"],["Insémination artificielle","Sperme déposé dans l’utérus"],["FIV","Fécondation en laboratoire, puis transfert de l’embryon dans l’utérus"],["ICSI","Un spermatozoïde injecté dans l’ovocyte"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"On parle d’infertilité après 12 mois sans grossesse. Combien de mois de plus que ce minimum le couple a-t-il attendus ?","aide":"Soustrais 12 à la durée relevée dans le bilan.","type":"nombre","unite":"mois"},{"enonce":"Touche le résultat qui explique l’infertilité du couple.","aide":"Les autres examens sont normaux : cherche le seul résultat anormal.","type":"zone","document":"bilan","multiple":false},{"enonce":"Quelle technique est adaptée à ce couple ?","aide":"La fécondation doit avoir lieu hors des trompes.","type":"choix","options":[{"id":"a","texte":"L’insémination artificielle, car le sperme est déposé dans l’utérus"},{"id":"b","texte":"La fécondation in vitro, avec transfert de l’embryon dans l’utérus"},{"id":"c","texte":"L’ICSI, car le problème vient de la qualité des spermatozoïdes"},{"id":"d","texte":"La stimulation ovarienne, car l’ovulation est la difficulté de Mme"}],"multiple":false},{"enonce":"Pourquoi l’insémination artificielle ne conviendrait-elle pas ici ?","aide":"Après le dépôt du sperme, où se passe la fécondation ?","type":"choix","options":[{"id":"a","texte":"Les spermatozoïdes devraient franchir les trompes obstruées pour atteindre l’ovocyte"},{"id":"b","texte":"L’ovulation est normale, donc le sperme ne peut plus être déposé"},{"id":"c","texte":"Les spermatozoïdes ne survivent jamais dans la cavité de l’utérus"},{"id":"d","texte":"Le spermogramme de Monsieur est normal, donc toute technique est interdite au couple"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 mois","explication":"18 − 12 = **6 mois** de plus : l’infertilité est avérée."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Ovulation et spermogramme sont normaux : la cause est l’**obstruction des deux trompes**, qui empêche la rencontre des gamètes."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec des trompes bouchées, la fécondation se fait **en laboratoire (FIV)**, puis l’embryon est transféré dans l’utérus."},{"cle":{"type":"choix","ids":["a"]},"explication":"Après l’insémination, la rencontre des gamètes se fait dans la **trompe** : si elle est obstruée, elle ne peut pas avoir lieu."}]$ex$::jsonb),
  ('e48e856a-120e-5736-bd4d-c1ae69d14a21'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce que les rayons X traversent","competence":"lire-graphique","situation":"Sur une radiographie du thorax, on distingue les côtes, les muscles et les poumons. Le graphique compare l’absorption des rayons X par trois milieux.","documents":[{"id":"abs","type":"graphique","forme":"barres","titre":"Absorption des rayons X","categories":["Air des poumons","Muscle","Os"],"series":[{"nom":"Absorption","valeurs":[2,30,90],"teinte":"turquoise"}],"axeY":{"titre":"Absorption","unite":"unités arbitraires","min":0,"max":100,"pas":20},"valeurs":false,"source":"Valeurs schématiques"}],"questions":[{"enonce":"Touche le milieu qui absorbe le plus les rayons X.","aide":"Cherche la barre la plus haute.","type":"zone","document":"abs","multiple":false},{"enonce":"Combien de fois l’os absorbe-t-il plus de rayons X que le muscle ?","aide":"Divise l’absorption de l’os par celle du muscle.","type":"nombre"},{"enonce":"Sur le cliché, quelle zone apparaît en noir ?","aide":"Une zone noire est une zone où beaucoup de rayons arrivent sur le détecteur.","type":"choix","options":[{"id":"a","texte":"Le cœur, dont la paroi laisse passer presque tous les rayons émis"},{"id":"b","texte":"Les poumons, remplis d’air, qui laissent passer presque tous les rayons"},{"id":"c","texte":"Les muscles, qui absorbent davantage les rayons que les os voisins"},{"id":"d","texte":"Les côtes, qui laissent passer presque tous les rayons en raison de leur densité"}],"multiple":false}]}$ex$::jsonb,
