  ('e48e856a-120e-5736-bd4d-c1ae69d14a21'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois échos dans les tissus","competence":"modeliser","situation":"Une sonde émet une brève impulsion d’ultrasons et enregistre trois échos, dans l’ordre où ils reviennent. Le schéma montre les trois interfaces rencontrées, de la plus proche à la plus éloignée.","documents":[{"id":"sonde","type":"schema","titre":"Sonde et interfaces (sans échelle)","largeur":340,"hauteur":260,"elements":[{"forme":"rect","x":125,"y":8,"l":90,"h":28,"arrondi":6,"texte":"Sonde","teinte":"gris","motif":"plein"},{"forme":"rect","x":95,"y":40,"l":150,"h":195,"teinte":"rose","motif":"clair"},{"forme":"rect","x":95,"y":80,"l":150,"h":8,"arrondi":0,"teinte":"encre","motif":"plein","id":"z1","zone":true},{"forme":"rect","x":95,"y":140,"l":150,"h":8,"arrondi":0,"teinte":"encre","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":95,"y":200,"l":150,"h":8,"arrondi":0,"teinte":"encre","motif":"plein","id":"z3","zone":true},{"forme":"texte","x":265,"y":90,"texte":"A","taille":"normal","ancre":"debut"},{"forme":"texte","x":265,"y":150,"texte":"B","taille":"normal","ancre":"debut"},{"forme":"texte","x":265,"y":210,"texte":"C","taille":"normal","ancre":"debut"},{"forme":"ligne","de":[60,45],"a":[60,228],"teinte":"encre","fleche":"fin"},{"forme":"texte","x":60,"y":250,"texte":"profondeur","taille":"petit","ancre":"milieu","italique":true}]},{"id":"echos","type":"tableau","titre":"Temps entre l’émission et le retour de l’écho","colonnes":["Écho","Durée (µs)"],"lignes":[["Écho n° 1","39"],["Écho n° 2","130"],["Écho n° 3","195"]],"enteteLignes":true,"source":"Vitesse des ultrasons dans les tissus mous : 1 540 m/s"}],"questions":[{"enonce":"Touche l’interface qui a renvoyé l’écho n° 2.","aide":"Plus une interface est profonde, plus son écho revient tard.","type":"zone","document":"sonde","multiple":false},{"enonce":"À quelle profondeur se trouve l’interface B ? Utilise d = v × Δt ÷ 2.","aide":"Convertis 130 µs en secondes (× 10⁻⁶), multiplie par 1 540 m/s, puis divise par 2 (aller et retour).","type":"nombre","unite":"cm"},{"enonce":"Quelle est l’épaisseur de la couche située entre l’interface B et l’interface C ?","aide":"Calcule la profondeur de C avec son écho, puis soustrais celle de B.","type":"nombre","unite":"cm"},{"enonce":"Une interface deux fois plus profonde que B renverrait son écho avec une durée :","aide":"Relis la formule d = v × Δt ÷ 2 : d et Δt sont-ils proportionnels ?","type":"choix","options":[{"id":"a","texte":"Deux fois plus longue, car l’aller-retour est deux fois plus long"},{"id":"b","texte":"Deux fois plus courte, car l’onde s’affaiblit en route"},{"id":"c","texte":"Identique, car la vitesse des ultrasons est constante"},{"id":"d","texte":"Quatre fois plus longue, car la distance est élevée au carré"}],"multiple":false}]}$ex$::jsonb,
