  ('e48e856a-120e-5736-bd4d-c1ae69d14a21'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une TEP au fluor 18","competence":"modeliser","situation":"Pour une tomographie par émission de positons (TEP), un patient reçoit du fluor 18, émetteur β⁺ dont la période est de 110 minutes. Voici le protocole et la décroissance de l’activité d’un échantillon.","documents":[{"id":"proto","type":"tableau","titre":"Protocole d’examen","colonnes":["Donnée","Valeur"],"lignes":[["Masse du patient","80 kg"],["Activité prescrite","4 MBq par kg"],["Injection du fluor 18","8 h 00"],["Début de l’examen","9 h 50"]],"enteteLignes":true,"source":"Protocole imaginé pour l’exercice"},{"id":"decr","type":"graphique","forme":"courbe","titre":"Décroissance d’un échantillon de fluor 18","categories":["0","110","220","330","440"],"series":[{"nom":"Activité","valeurs":[320,160,80,40,20],"teinte":"violet"}],"axeY":{"titre":"Activité","unite":"MBq","min":0,"max":350,"pas":50},"axeX":{"titre":"Temps écoulé (min)"},"valeurs":false,"source":"Échantillon de 320 MBq à l’instant 0"}],"questions":[{"enonce":"Quelle activité faut-il injecter à ce patient ?","aide":"Multiplie l’activité par kilogramme par la masse du patient.","type":"nombre","unite":"MBq"},{"enonce":"Touche l’instant où l’activité est divisée par deux pour la première fois.","aide":"Cherche la valeur égale à la moitié de 320 MBq.","type":"zone","document":"decr","multiple":false},{"enonce":"Quelle activité reste-t-il dans le corps du patient au début de l’examen, à 9 h 50 ? On néglige l’élimination par l’organisme.","aide":"Calcule le temps écoulé entre 8 h 00 et 9 h 50, puis compare-le à la période.","type":"nombre","unite":"MBq"},{"enonce":"Pourquoi choisit-on un noyau de période courte comme le fluor 18 pour un examen ?","aide":"Une période courte veut dire que la source s’éteint rapidement.","type":"choix","options":[{"id":"a","texte":"Son activité reste constante, ce qui garantit une image très stable"},{"id":"b","texte":"Son activité diminue vite, ce qui limite la durée de l’irradiation du patient"},{"id":"c","texte":"Sa période est de plusieurs mois, donc on peut refaire l’examen le lendemain"},{"id":"d","texte":"Son rayonnement ne traverse jamais les tissus et reste au même endroit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":320,"tolerance":0},"affichage":"320 MBq","explication":"4 × 80 = **320 MBq**."},{"cle":{"type":"zone","ids":["k1"]},"explication":"L’activité passe de 320 à 160 MBq après **110 min** : c’est la période du fluor 18."},{"cle":{"type":"nombre","valeur":160,"tolerance":5},"affichage":"160 MBq","explication":"De 8 h 00 à 9 h 50, il s’écoule **110 min**, soit une période : l’activité est divisée par deux, il reste **160 MBq**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec une période de 110 min, l’activité baisse vite : l’examen reste possible mais l’**irradiation est limitée dans le temps**."}]$ex$::jsonb),
  ('7db92b49-bd5f-5849-965b-ae0598746b0a'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le bilan sanguin de Malik","competence":"lire-tableau","situation":"Malik, 17 ans, reçoit les résultats d’une prise de sang faite à jeun. Ils sont comparés aux valeurs de référence d’un adulte. Un médecin les interprète toujours avec le contexte clinique.","documents":[{"id":"bilan","type":"tableau","titre":"Résultats d’analyse (imaginés)","colonnes":["Paramètre","Résultat","Valeurs de référence"],"lignes":[["Glycémie à jeun","0,86 g/L","0,70 à 1,10 g/L"],["Natrémie","141 mmol/L","135 à 145 mmol/L"],["Kaliémie","5,4 mmol/L","3,5 à 5,0 mmol/L"]],"enteteLignes":true,"source":"Résultats imaginés pour l’exercice"}],"questions":[{"enonce":"Touche le résultat situé en dehors des valeurs de référence.","aide":"Compare chaque résultat à l’intervalle de sa ligne.","type":"zone","document":"bilan","multiple":false},{"enonce":"De combien la kaliémie dépasse-t-elle la limite haute des valeurs de référence ?","aide":"Soustrais la limite haute (5,0) au résultat.","type":"nombre","unite":"mmol/L"},{"enonce":"La glycémie de Malik est de 0,86 g/L. Quelle est-elle en mmol/L, arrondie au dixième ? Masse molaire du glucose : 180 g/mol.","aide":"C = Cm ÷ M, en mol/L ; multiplie ensuite par 1 000 pour passer en mmol/L.","type":"nombre","unite":"mmol/L"},{"enonce":"Que signifie un résultat hors des valeurs de référence ?","aide":"Relis la dernière phrase du cours sur les normes.","type":"choix","options":[{"id":"a","texte":"Il oriente le diagnostic, à confirmer par d’autres examens et le contexte clinique"},{"id":"b","texte":"Il impose de refaire toutes les analyses de sang dans la journée même"},{"id":"c","texte":"Il n’a aucune importance, car les valeurs de référence sont approximatives"},{"id":"d","texte":"Il prouve à lui seul l’existence d’une maladie précise chez le patient"}],"multiple":false}]}$ex$::jsonb,
