e":"choix","options":[{"id":"a","texte":"L’élimination rapide d’une substance par l’organisme, qui en perd à chaque repas"},{"id":"b","texte":"La bioaccumulation d’une substance persistante, qui se concentre le long de la chaîne alimentaire"},{"id":"c","texte":"La dilution d’un polluant dans l’eau de mer, qui le rend plus faible en haut de chaîne"},{"id":"d","texte":"L’acidification des océans, qui détruit peu à peu les organismes du plancton"}],"multiple":false}]}$ex$::jsonb,
