   $ex${"titre":"Le cancer et l’âge","competence":"lire-graphique","situation":"Le graphique donne, de façon schématique, le nombre de nouveaux cas d’un cancer pour 100 000 personnes selon la tranche d’âge.","documents":[{"id":"age","type":"graphique","forme":"barres","titre":"Nouveaux cas pour 100 000 personnes","categories":["20-29","30-39","40-49","50-59","60-69","70-79"],"series":[{"nom":"Nouveaux cas","valeurs":[10,40,120,300,600,900],"teinte":"violet"}],"axeY":{"titre":"Cas pour 100 000","unite":"personnes","min":0,"max":1000,"pas":200},"axeX":{"titre":"Tranche d’âge (ans)"},"valeurs":false,"source":"Valeurs schématiques, pour l’exercice"}],"questions":[{"enonce":"Touche la tranche d’âge où il y a le plus de nouveaux cas.","aide":"Cherche la barre la plus haute.","type":"zone","document":"age","multiple":false},{"enonce":"Combien de fois y a-t-il plus de nouveaux cas chez les 60-69 ans que chez les 40-49 ans ?","aide":"Lis les deux valeurs puis divise la plus grande par la plus petite.","type":"nombre","unite":"fois"},{"enonce":"Quelle explication permet de comprendre cette augmentation avec l’âge ?","aide":"Une seule mutation ne suffit généralement pas à faire un cancer.","type":"choix","options":[{"id":"a","texte":"Il faut en général accumuler plusieurs mutations, ce qui prend du temps"},{"id":"b","texte":"L’ADN des personnes âgées est plus riche en gènes freinant la division"},{"id":"c","texte":"Les cellules âgées cessent de se diviser et se transforment en cancer"},{"id":"d","texte":"Le cancer se transmet d’une personne âgée à l’autre par contagion"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k5"]},"explication":"La barre la plus haute est celle des **70-79 ans**, avec environ 900 cas pour 100 000 personnes."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 fois","explication":"Chez les 60-69 ans, environ 600 cas ; chez les 40-49 ans, environ 120 : 600 ÷ 120 = **5** fois plus."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un cancer demande en général **plusieurs mutations** successives dans la même cellule : plus on vieillit, plus elles ont eu le temps de s’accumuler."}]$ex$::jsonb),
  ('5b732eb5-bc03-52cd-b111-02db1c4d0249'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le parcours de Madame L.","competence":"analyser-texte","situation":"Le parcours de soins ci-dessous est imaginé. Il illustre les étapes de dépistage, de diagnostic et de traitement d’un cancer du sein.","documents":[{"id":"dossier","type":"texte","genre":"article","titre":"Dossier de Madame L., 58 ans (cas imaginé)","auteur":"Texte écrit pour l’exercice","blocs":["Madame L. participe au dépistage organisé : une mammographie montre une petite opacité dans le sein droit.","Une échographie confirme l’anomalie. Une biopsie est réalisée ; l’examen anatomopathologique du fragment conclut à un cancer.","Le dosage d’un marqueur tumoral sanguin revient normal. Un scanner ne trouve aucune métastase.","L’équipe propose une tumorectomie, suivie de séances de radiothérapie."]},{"id":"traitements","type":"tableau","titre":"Quelques traitements et leur principe","colonnes":["Traitement","Principe"],"lignes":[["Chirurgie","Retirer la tumeur"],["Radiothérapie","Rayonnements ionisants sur la zone tumorale"],["Chimiothérapie","Médicaments qui bloquent la division cellulaire"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne l’examen du tissu au microscope, celui qui a affirmé le diagnostic.","aide":"Un fragment de tissu est regardé au microscope : c’est cet examen qui tranche.","type":"zone","document":"dossier","multiple":false},{"enonce":"Le marqueur tumoral de Madame L. est normal. Que peut-on en conclure ?","aide":"Relis comment le diagnostic a été réellement établi dans le dossier.","type":"choix","options":[{"id":"a","texte":"Cela prouve que la tumeur est bénigne et ne donnera pas de métastases"},{"id":"b","texte":"Cela montre que le dépistage organisé par mammographie n’a aucun intérêt"},{"id":"c","texte":"Cela prouve qu’il n’y a pas de cancer, donc la biopsie était inutile"},{"id":"d","texte":"Cela n’exclut pas un cancer : il ne sert pas à poser le diagnostic"}],"multiple":false},{"enonce":"Pourquoi la chimiothérapie provoque-t-elle la chute des cheveux ?","aide":"Regarde le principe du traitement dans le tableau : que bloque-t-il ?","type":"choix","options":[{"id":"a","texte":"Elle est appliquée directement sur le crâne, où elle détruit les racines des cheveux"},{"id":"b","texte":"Elle déclenche une allergie cutanée qui entraîne la perte de tous les cheveux"},{"id":"c","texte":"Elle agit uniquement sur les cellules cancéreuses, donc les cheveux tombent par âge"},{"id":"d","texte":"Elle frappe aussi les cellules saines qui se divisent vite, comme celles des follicules pileux"}],"multiple":false},{"enonce":"Touche le mot qui désigne l’examen d’imagerie du dépistage organisé.","aide":"Cet examen est une radiographie du sein.","type":"zone","document":"dossier","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"Seul l’examen **anatomopathologique** du tissu prélevé par biopsie affirme le cancer ; l’imagerie le fait seulement suspecter."},{"cle":{"type":"choix","ids":["d"]},"explication":"Un marqueur normal **n’exclut pas** un cancer et un marqueur élevé ne le prouve pas : le diagnostic repose sur l’examen anatomopathologique."},{"cle":{"type":"choix","ids":["d"]},"explication":"La chimiothérapie bloque la division cellulaire. Les cellules **saines à renouvellement rapide** (follicules pileux, muqueuses, sang) sont touchées aussi."},{"cle":{"type":"zone","ids":["m7"]},"explication":"La **mammographie** est l’examen d’imagerie du dépistage organisé, proposé aux femmes de 50 à 74 ans."}]$ex$::jsonb),
  ('a727c1eb-c7d2-571a-ae72-2be239d226de'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Décoder les mots de la médecine","competence":"comprendre-langue","situation":"Un compte rendu d’hôpital (imaginé) contient des mots savants. Chacun se découpe en morceaux qu’on sait traduire.","documents":[{"id":"cr","type":"texte","genre":"article","titre":"Extrait d’un compte rendu (imaginé)","auteur":"Texte écrit pour l’exercice","blocs":["Le patient présente une néphrite et une polyurie.","L’examen note une hépatomégalie ainsi qu’une bradycardie.","Aucune dysphagie n’est signalée."]},{"id":"morceaux","type":"tableau","titre":"Les morceaux à connaître","colonnes":["Morceau","Sens"],"lignes":[["néphro-","Rein"],["hépato-","Foie"],["poly-","Beaucoup"],["brady-","Lent"],["dys-","Difficulté, anomalie"],["-ite","Inflammation"],["-urie","Présence dans l’urine, urine"],["-mégalie","Augmentation de volume"],["-phagie","Action de manger, avaler"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne une inflammation du rein.","aide":"Cherche un mot qui commence par le morceau « rein » et finit par celui de l’inflammation.","type":"zone","document":"cr","multiple":false},{"enonce":"Associe chaque mot à son sens.","aide":"Découpe chaque mot en deux morceaux et traduis-les avec le tableau.","type":"association","gauche":[{"id":"g0","texte":"Polyurie"},{"id":"g1","texte":"Hépatomégalie"},{"id":"g2","texte":"Bradycardie"},{"id":"g3","texte":"Dysphagie"}],"droite":[{"id":"d0","texte":"Urines très abondantes"},{"id":"d1","texte":"Difficulté à avaler"},{"id":"d2","texte":"Cœur lent"},{"id":"d3","texte":"Foie augmenté de volume"}]},{"enonce":"Une « cardiomégalie » est l’augmentation de volume de quel organe ?","aide":"Le morceau « cardio- » se retrouve dans « bradycardie » : quel organe bat ?","type":"choix","options":[{"id":"a","texte":"Du rein"},{"id":"b","texte":"De la rate"},{"id":"c","texte":"Du cœur"},{"id":"d","texte":"Du foie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**Néphrite** = néphro- (rein) + -ite (inflammation) : une inflammation du rein."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"**Polyurie** : beaucoup d’urine ; **hépatomégalie** : foie augmenté de volume ; **bradycardie** : cœur lent ; **dysphagie** : difficulté à avaler."},{"cle":{"type":"choix","ids":["c"]},"explication":"Cardio- désigne le cœur et -mégalie une augmentation de volume : une **cardiomégalie** est un cœur augmenté de volume."}]$ex$::jsonb),
  ('a727c1eb-c7d2-571a-ae72-2be239d226de'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le calcul du comprimé","competence":"calculer","situation":"Un comprimé imaginé contient 500 mg de paracétamol, de formule C₈H₉NO₂. On veut savoir combien de moles cela représente, en appliquant les réflexes de l’épreuve de chimie.","documents":[{"id":"donnees","type":"tableau","titre":"Données","colonnes":["Grandeur","Valeur"],"lignes":[["Masse de paracétamol dans un comprimé","500 mg"],["Formule du paracétamol","C₈H₉NO₂"],["M(C)","12 g/mol"],["M(H)","1 g/mol"],["M(N)","14 g/mol"],["M(O)","16 g/mol"]],"enteteLignes":true,"source":"Comprimé imaginé pour l’exercice"}],"questions":[{"enonce":"Convertis d’abord la masse du comprimé en grammes.","aide":"Il y a 1 000 mg dans 1 g.","type":"nombre","unite":"g"},{"enonce":"Calcule la masse molaire M du paracétamol C₈H₉NO₂.","aide":"Additionne la masse de chaque atome : 8 fois M(C), 9 fois M(H), 1 fois M(N), 2 fois M(O).","type":"nombre","unite":"g/mol"},{"enonce":"Avant de remplacer par les valeurs, on écrit la formule littérale. Comment obtient-on la quantité de matière n ?","aide":"La quantité de matière est le nombre de fois que la masse molaire « rentre » dans la masse.","type":"choix","options":[{"id":"a","texte":"La masse additionnée à la masse molaire"},{"id":"b","texte":"La masse molaire divisée par la masse"},{"id":"c","texte":"La masse multipliée par la masse molaire"},{"id":"d","texte":"La masse divisée par la masse molaire"}],"multiple":false},{"enonce":"Calcule la quantité de matière de paracétamol dans un comprimé, en millimoles (mmol), arrondie au centième.","aide":"n = m ÷ M, avec m en grammes ; 1 mol = 1 000 mmol.","type":"nombre","unite":"mmol"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.5,"tolerance":0},"affichage":"0,5 g","explication":"500 mg ÷ 1 000 = **0,5 g**. On convertit toujours les unités avant de calculer."},{"cle":{"type":"nombre","valeur":151,"tolerance":0},"affichage":"151 g/mol","explication":"M = 8 × 12 + 9 × 1 + 14 + 2 × 16 = 96 + 9 + 14 + 32 = **151 g/mol**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La quantité de matière est **n = m ÷ M**, avec m en grammes et M en g/mol."},{"cle":{"type":"nombre","valeur":3.31,"tolerance":0.02},"affichage":"3,31 mmol","explication":"n = 0,5 ÷ 151 ≈ 3,31 × 10⁻³ mol, soit **3,31 mmol**."}]$ex$::jsonb),
  ('a727c1eb-c7d2-571a-ae72-2be239d226de'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Décrire, puis interpréter","competence":"analyser-document","situation":"Un patient de 34 ans (cas imaginé) consulte pour de la fièvre, des frissons et une toux. Les résultats de sa prise de sang sont donnés avec les valeurs de référence.","documents":[{"id":"nfs","type":"tableau","titre":"Résultats d’analyse du patient","colonnes":["Examen","Résultat","Valeurs de référence"],"lignes":[["Leucocytes","15 500 /mm³","4 000 à 10 000 /mm³"],["Polynucléaires neutrophiles","12 800 /mm³","1 800 à 7 000 /mm³"],["Lymphocytes","1 900 /mm³","1 500 à 4 000 /mm³"],["Protéine C réactive (CRP)","96 mg/L","Moins de 5 mg/L"]],"enteteLignes":true,"source":"Cas imaginé, valeurs arrondies"}],"questions":[{"enonce":"Trie ces éléments : signes cliniques (ressentis ou constatés à l’examen) ou signes paracliniques (résultats d’examens complémentaires).","aide":"Un signe paraclinique sort d’un laboratoire ou d’une imagerie.","type":"categories","categories":[{"id":"c0","texte":"Signes cliniques"},{"id":"c1","texte":"Signes paracliniques"}],"items":[{"id":"i0","texte":"Toux"},{"id":"i1","texte":"CRP à 96 mg/L"},{"id":"i2","texte":"Leucocytes à 15 500 /mm³"},{"id":"i3","texte":"Fièvre mesurée au cabinet"},{"id":"i4","texte":"Polynucléaires à 12 800 /mm³"},{"id":"i5","texte":"Frissons"}]},{"enonce":"Touche la seule ligne dont le résultat reste dans les valeurs de référence.","aide":"Compare chaque résultat à sa fourchette de référence.","type":"zone","document":"nfs","multiple":false},{"enonce":"Quelle phrase interprète correctement le document, au lieu de simplement le décrire ?","aide":"Interpréter, c’est relier un constat à une connaissance pour en tirer une conclusion.","type":"choix","options":[{"id":"a","texte":"Les résultats sont élevés et les valeurs de référence sont plus basses que celles du patient"},{"id":"b","texte":"Le patient a de la fièvre, des frissons et une toux depuis quelques jours seulement"},{"id":"c","texte":"Les leucocytes valent 15 500 par mm³ et la référence va de 4 000 à 10 000 par mm³"},{"id":"d","texte":"Les polynucléaires neutrophiles augmentent et la CRP monte : cela oriente vers une infection bactérienne"}],"multiple":false},{"enonce":"Range les étapes de la démarche attendue devant un cas clinique.","aide":"On va du constat vers la conclusion, et le traitement vient en dernier.","type":"ordre","items":[{"id":"a","texte":"Relever les signes paracliniques et les comparer aux valeurs de référence"},{"id":"b","texte":"Relever les signes cliniques"},{"id":"c","texte":"Présenter et justifier le traitement et la prévention"},{"id":"d","texte":"Relier les signes au mécanisme de la maladie"},{"id":"e","texte":"Nommer la pathologie et expliquer le diagnostic"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Les **signes cliniques** (frissons, toux, fièvre) se ressentent ou s’observent ; les **signes paracliniques** (CRP, leucocytes, polynucléaires) sont des résultats d’examens."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Les **lymphocytes** (1 900 /mm³) sont dans la fourchette de 1 500 à 4 000 /mm³ ; les autres résultats la dépassent."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les trois autres phrases ne font que **décrire**. La bonne relie le constat (neutrophiles et CRP élevés) à une connaissance : cela **oriente vers une infection bactérienne**."},{"cle":{"type":"ordre","ids":["b","a","d","e","c"]},"explication":"D’abord relever les signes, puis les **interpréter** par le mécanisme, nommer la pathologie, et enfin traiter et prévenir."}]$ex$::jsonb),
  ('b7f02856-3fcb-5926-8ea9-0f65459eb690'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le trajet de l’urine","competence":"observer-schema","situation":"Sur une planche d’anatomie, l’appareil urinaire est dessiné de face, sans légende. À toi de reconnaître les organes.","documents":[{"id":"urin","type":"schema","titre":"Appareil urinaire, vu de face","largeur":320,"hauteur":260,"elements":[{"forme":"ellipse","cx":95,"cy":60,"rx":26,"ry":40,"teinte":"rose","motif":"clair","id":"z1","zone":true},{"forme":"ellipse","cx":225,"cy":60,"rx":26,"ry":40,"teinte":"rose","motif":"clair","id":"z2","zone":true},{"forme":"ligne","de":[112,95],"a":[140,170],"id":"z3","zone":true,"teinte":"rose"},{"forme":"ligne","de":[208,95],"a":[180,170],"id":"z4","zone":true,"teinte":"rose"},{"forme":"ellipse","cx":160,"cy":190,"rx":36,"ry":26,"teinte":"rose","motif":"clair","id":"z5","zone":true},{"forme":"ligne","de":[160,216],"a":[160,248],"id":"z6","zone":true,"teinte":"rose"},{"forme":"texte","x":160,"y":12,"texte":"Schéma simplifié, sans échelle","taille":"petit","ancre":"milieu","italique":true}]}],"questions":[{"enonce":"Touche l’organe qui stocke l’urine entre deux mictions.","aide":"C’est l’organe en forme de poche, situé en bas du schéma.","type":"zone","document":"urin","multiple":false},{"enonce":"Touche les deux organes qui fabriquent l’urine.","aide":"Ils contiennent chacun environ un million de néphrons.","type":"zone","document":"urin","multiple":true},{"enonce":"Range les organes dans l’ordre où l’urine les traverse.","aide":"L’urine est fabriquée d’abord, évacuée en dernier.","type":"ordre","items":[{"id":"a","texte":"Uretère"},{"id":"b","texte":"Urètre"},{"id":"c","texte":"Vessie"},{"id":"d","texte":"Rein"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"La **vessie** stocke l’urine avant son évacuation par l’urètre."},{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"Les deux **reins** fabriquent l’urine : ils filtrent le plasma puis modifient sa composition."},{"cle":{"type":"ordre","ids":["d","a","c","b"]},"explication":"Rein, **uretère**, vessie, urètre : l’urine est fabriquée, transportée, stockée puis évacuée."}]$ex$::jsonb),
  ('b7f02856-3fcb-5926-8ea9-0f65459eb690'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ce que le rein garde et ce qu’il jette","competence":"calculer","situation":"Chaque jour, les reins filtrent environ 180 L de plasma et l’organisme émet environ 1,5 L d’urine. Le tableau compare trois liquides.","documents":[{"id":"comp","type":"tableau","titre":"Composition (en g/L)","colonnes":["Constituant","Plasma","Urine primitive","Urine définitive"],"lignes":[["Protéines","70","0","0"],["Glucose","1","1","0"],["Urée","0,3","0,3","20"]],"enteteLignes":true,"source":"Valeurs moyennes arrondies"}],"questions":[{"enonce":"Quelle masse de glucose les reins filtrent-ils par jour, sachant que l’urine primitive en contient 1 g/L ?","aide":"Multiplie le volume filtré par jour par la concentration.","type":"nombre","unite":"g"},{"enonce":"Pourquoi l’urine définitive ne contient-elle plus de glucose ?","aide":"Compare le glucose dans l’urine primitive et dans l’urine définitive.","type":"choix","options":[{"id":"a","texte":"Il n’est jamais filtré, car ses molécules sont trop grosses"},{"id":"b","texte":"Il est entièrement réabsorbé dans le sang le long du tube du néphron"},{"id":"c","texte":"Il est détruit dans la vessie par les enzymes de l’urine"},{"id":"d","texte":"Il est sécrété dans le tube puis transformé en urée par le rein"}],"multiple":false},{"enonce":"Quelle masse d’urée est éliminée par jour dans 1,5 L d’urine définitive à 20 g/L ?","aide":"Volume d’urine par jour multiplié par la concentration en urée.","type":"nombre","unite":"g"},{"enonce":"Quel pourcentage de l’eau filtrée retourne dans le sang ? Arrondis au dixième.","aide":"Eau réabsorbée = eau filtrée − urine émise ; divise par l’eau filtrée.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":180,"tolerance":0},"affichage":"180 g","explication":"180 L × 1 g/L = **180 g** de glucose filtrés par jour, que le rein réabsorbe normalement en totalité."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le glucose passe dans l’urine primitive (il est filtré) puis **retourne dans le sang** par réabsorption tubulaire : il n’apparaît plus dans l’urine définitive."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 g","explication":"1,5 L × 20 g/L = **30 g** d’urée éliminés par jour, alors que 180 L × 0,3 g/L = 54 g ont été filtrés : le tube en réabsorbe une partie."},{"cle":{"type":"nombre","valeur":99.2,"tolerance":0.1},"affichage":"99,2 %","explication":"(180 − 1,5) ÷ 180 × 100 ≈ **99,2 %** : plus de 99 % de l’eau filtrée est réabsorbée."}]$ex$::jsonb),
  ('b7f02856-3fcb-5926-8ea9-0f65459eb690'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le devenir d’un médicament","competence":"lire-graphique","situation":"Un médicament imaginé est pris par la bouche à l’instant 0. Le graphique montre sa concentration dans le plasma au cours du temps (courbe schématique).","documents":[{"id":"med","type":"graphique","forme":"courbe","titre":"Concentration plasmatique du médicament","categories":["0 h","2 h","4 h","6 h","8 h","10 h"],"series":[{"nom":"Concentration","valeurs":[0,10,5,2.5,1.25,0.6],"teinte":"violet"}],"axeY":{"titre":"Concentration","unite":"mg/L","min":0,"max":10,"pas":2},"axeX":{"titre":"Temps après la prise"},"valeurs":false,"source":"Courbe schématique, médicament imaginé"}],"questions":[{"enonce":"Touche le moment où la concentration dans le plasma est maximale.","aide":"Cherche le sommet de la courbe.","type":"zone","document":"med","multiple":false},{"enonce":"Entre 2 h et 4 h, la concentration est divisée par 2. Au bout de combien d’heures après le pic atteint-elle le quart de sa valeur maximale ?","aide":"Le quart de 10 mg/L vaut 2,5 mg/L : trouve quand la courbe y arrive, puis compte depuis le pic.","type":"nombre","unite":"h"},{"enonce":"Après le pic, la concentration diminue. Quels organes sont les principaux responsables de cette baisse ?","aide":"Un xénobiotique est transformé par un organe puis éliminé par un autre.","type":"choix","options":[{"id":"a","texte":"L’estomac, qui le reprend, et la vessie, qui le transforme en glucose"},{"id":"b","texte":"Le cœur, qui détruit le médicament, et les poumons, qui le stockent"},{"id":"c","texte":"Le foie, qui transforme la substance, et les reins, qui l’éliminent dans l’urine"},{"id":"d","texte":"La rate, qui le fabrique, et la peau, qui le garde sous forme de graisse"}],"multiple":false},{"enonce":"Si les reins éliminaient moins bien ce médicament, comment la courbe évoluerait-elle après le pic ?","aide":"Une élimination plus faible laisse la substance plus longtemps en circulation.","type":"choix","options":[{"id":"a","texte":"Elle monterait sans fin : la substance serait fabriquée par l’organisme lui-même"},{"id":"b","texte":"Elle descendrait plus vite : la substance serait éliminée par un autre organe"},{"id":"c","texte":"Elle resterait nulle : la substance ne passerait plus du tout dans le plasma"},{"id":"d","texte":"Elle descendrait plus lentement : la substance resterait plus longtemps dans le sang"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1"]},"explication":"Le maximum est atteint **2 h** après la prise : le médicament a été absorbé puis distribué par le sang."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 h","explication":"Le quart de 10 mg/L est 2,5 mg/L, atteint à 6 h, donc **4 h** après le pic (2 h pour diviser par 2, encore 2 h pour diviser par 2 à nouveau)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le médicament est surtout **métabolisé par le foie** puis éliminé, en grande partie, par les **reins** dans l’urine."},{"cle":{"type":"choix","ids":["d"]},"explication":"Avec une élimination rénale réduite, la concentration **diminue plus lentement** : c’est pourquoi le devenir d’un médicament explique ses doses et ses intervalles de prise."}]$ex$::jsonb),
  ('5028cb6a-9ae4-5fc1-a109-7882364a0197'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La glycémie après un repas","competence":"lire-graphique","situation":"Une personne en bonne santé mange à l’instant 0. On mesure sa glycémie toutes les 30 minutes (courbe schématique).","documents":[{"id":"gly","type":"graphique","forme":"courbe","titre":"Glycémie après un repas","categories":["0","30","60","90","120","150"],"series":[{"nom":"Glycémie","valeurs":[0.9,1.4,1.2,1.05,0.95,0.9],"teinte":"violet"}],"axeY":{"titre":"Glycémie","unite":"g/L","min":0.6,"max":1.6,"pas":0.2},"axeX":{"titre":"Minutes après le repas"},"valeurs":false,"source":"Courbe schématique"}],"questions":[{"enonce":"Touche le moment où la glycémie est la plus élevée.","aide":"Cherche le sommet de la courbe.","type":"zone","document":"gly","multiple":false},{"enonce":"De combien la glycémie augmente-t-elle entre le début du repas et le maximum ?","aide":"Soustrais la valeur de départ à la valeur maximale.","type":"nombre","unite":"g/L"},{"enonce":"Après le maximum, la glycémie baisse. Que font alors les muscles et le tissu adipeux ?","aide":"La glycémie baisse : le glucose sort du sang pour entrer dans des cellules.","type":"choix","options":[{"id":"a","texte":"Ils transforment le glucose en urée avant de l’envoyer au rein"},{"id":"b","texte":"Ils absorbent du glucose du sang sous l’action de l’insuline"},{"id":"c","texte":"Ils libèrent du glucose dans le sang sous l’action du glucagon"},{"id":"d","texte":"Ils cessent d’utiliser le glucose pour laisser la place aux graisses"}],"multiple":false},{"enonce":"Deux heures après le repas, la glycémie est revenue près de sa valeur de départ. Que montre ce retour ?","aide":"Le mot à retrouver décrit un milieu intérieur maintenu constant.","type":"choix","options":[{"id":"a","texte":"Que l’organisme a cessé d’utiliser du glucose pour se nourrir"},{"id":"b","texte":"Que la glycémie est régulée autour d’une valeur de consigne"},{"id":"c","texte":"Que l’insuline est sécrétée en permanence à la même dose"},{"id":"d","texte":"Que le repas n’a apporté aucun sucre à l’organisme du tout"}],"multiple":false}]}$ex$::jsonb,
