  ('baf14f01-e74c-54bb-a10d-5b1ff44bb209'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Comment naît une population résistante","competence":"raisonner","situation":"Dans une expérience imaginée, on fait pousser des bactéries dans un milieu où l’on ajoute un antibiotique à 4 h. Quelques bactéries résistantes étaient présentes dès le début. Le tableau donne les effectifs (unités arbitraires).","documents":[{"id":"pop","type":"tableau","titre":"Effectifs de bactéries","colonnes":["Temps","0 h","2 h","4 h","6 h","8 h","10 h"],"lignes":[["Bactéries sensibles","1 000","2 000","4 000","400","40","4"],["Bactéries résistantes","1","2","4","8","16","32"]],"enteteLignes":true,"source":"Expérience imaginée, antibiotique ajouté à 4 h"}],"questions":[{"enonce":"Combien de bactéries y a-t-il au total à 10 h ?","aide":"Additionne les sensibles et les résistantes de la dernière colonne.","type":"nombre","unite":"bactéries"},{"enonce":"À 10 h, quel pourcentage des bactéries est résistant ? Arrondis à l’unité.","aide":"Divise les résistantes par le total, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Range les étapes qui expliquent ce résultat.","aide":"Le traitement ne crée pas la résistance : il trie les bactéries.","type":"ordre","items":[{"id":"a","texte":"Les rares bactéries résistantes survivent et se multiplient"},{"id":"b","texte":"La population devient en grande partie résistante"},{"id":"c","texte":"Un antibiotique est ajouté au milieu"},{"id":"d","texte":"Les bactéries sensibles meurent"}]},{"enonce":"Que montre cette expérience sur l’usage des antibiotiques ?","aide":"Dans le tableau, que deviennent les bactéries résistantes quand les autres disparaissent ?","type":"choix","options":[{"id":"a","texte":"Les bactéries résistantes naissent de l’antibiotique lui-même"},{"id":"b","texte":"Un antibiotique rend toutes les bactéries résistantes en quelques heures"},{"id":"c","texte":"Les bactéries résistantes ne se reproduisent plus après l’antibiotique"},{"id":"d","texte":"Chaque usage inutile favorise la sélection de souches résistantes"}],"multiple":false}]}$ex$::jsonb,
