   $ex${"titre":"La fièvre qui repart","competence":"raisonner","situation":"Un adulte (cas imaginé) a la grippe. Sa température est relevée chaque jour. Au septième jour, une prise de sang est faite car la fièvre est revenue.","documents":[{"id":"temp","type":"graphique","forme":"courbe","titre":"Température au fil des jours","categories":["J1","J2","J3","J4","J5","J6","J7","J8"],"series":[{"nom":"Température","valeurs":[37,39.2,39.8,39,38,37.4,38.8,39],"teinte":"corail"}],"axeY":{"titre":"Température","unite":"°C","min":37,"max":40,"pas":1},"axeX":{"titre":"Jour"},"valeurs":false,"source":"Courbe imaginée pour l’exercice"},{"id":"bilan","type":"tableau","titre":"Prise de sang au jour 7","colonnes":["Examen","Résultat","Référence"],"lignes":[["Polynucléaires neutrophiles","11 000 /mm³","1 800 à 7 000 /mm³"],["Protéine C réactive (CRP)","120 mg/L","Moins de 5 mg/L"]],"enteteLignes":true,"source":"Cas imaginé, valeurs arrondies"}],"questions":[{"enonce":"Touche le jour où la fièvre repart à la hausse après une amélioration.","aide":"Repère le creux de la courbe, puis le jour qui suit.","type":"zone","document":"temp","multiple":false},{"enonce":"De combien le nombre de polynucléaires neutrophiles dépasse-t-il la limite haute de référence ?","aide":"Soustrais la limite haute au résultat.","type":"nombre","unite":"/mm³"},{"enonce":"Quelle hypothèse ces résultats permettent-ils de formuler ?","aide":"Les polynucléaires neutrophiles et la CRP orientent vers un type précis d’infection.","type":"choix","options":[{"id":"a","texte":"Une nouvelle grippe, provoquée par le même virus, qui guérit seule"},{"id":"b","texte":"Une allergie, parce que les éosinophiles sont très élevés ici"},{"id":"c","texte":"Une carence en plaquettes, responsable de la reprise de la fièvre"},{"id":"d","texte":"Une infection bactérienne venue s’ajouter à la grippe, appelée surinfection"}],"multiple":false},{"enonce":"Pourquoi un antibiotique ne traite-t-il pas la grippe elle-même ?","aide":"Un antibiotique vise des structures propres aux bactéries.","type":"choix","options":[{"id":"a","texte":"Le virus de la grippe n’a ni paroi ni ribosome sur lesquels il agirait"},{"id":"b","texte":"Le virus de la grippe se cache dans les os où il est inaccessible"},{"id":"c","texte":"Le virus de la grippe modifie chaque semaine son propre ADN"},{"id":"d","texte":"Le virus de la grippe est détruit par le foie avant toute action"}],"multiple":false}]}$ex$::jsonb,
