   $ex${"titre":"Lire la vaccination sans se tromper","competence":"lire-tableau","situation":"Le CCAS de Val-Clair, ville imaginaire, présente l’évolution de la vaccination contre la grippe chez les 65 ans et plus. Avant de rédiger, il faut lire les chiffres avec justesse.","documents":[{"id":"vac","type":"tableau","titre":"Part des 65 ans et plus vaccinés contre la grippe","source":"Chiffres imaginés pour l’exercice.","colonnes":["Année","2019","2023"],"lignes":[["Personnes vaccinées (%)",40,52]],"enteteLignes":true}],"questions":[{"enonce":"Touche la part de personnes vaccinées en 2023.","aide":"Repère la colonne 2023 dans le tableau.","type":"zone","document":"vac","multiple":false},{"enonce":"De combien de points la part de personnes vaccinées a-t-elle augmenté entre 2019 et 2023 ?","aide":"Fais la différence entre les deux pourcentages.","type":"nombre","unite":"points"},{"enonce":"Quel est le taux de variation de cette part entre 2019 et 2023, en % ?","aide":"Calcule (arrivée − départ) ÷ départ × 100.","type":"nombre","unite":"%"},{"enonce":"Quelle phrase de lecture est correcte ?","aide":"Ne confonds pas points et pourcentage.","type":"choix","options":[{"id":"a","texte":"La part de vaccinés est passée de 40 % à 52 %, soit une hausse de 12 points."},{"id":"b","texte":"La part de vaccinés est passée de 52 % à 40 %, soit une baisse de 12 points."},{"id":"c","texte":"La part de vaccinés est passée de 40 % à 52 %, soit une hausse de 12 %."},{"id":"d","texte":"La part de vaccinés est passée de 40 % à 52 %, soit une hausse de 30 points."}],"multiple":false}]}$ex$::jsonb,
