   $ex${"titre":"Le renoncement aux soins, en dossier","competence":"analyser-document","situation":"Tu prépares la seconde partie de l’épreuve : un petit dossier de deux documents sur le renoncement aux soins dans une ville imaginaire. Tu dois lire, calculer puis organiser tes arguments.","documents":[{"id":"doc1","type":"texte","genre":"article","titre":"Document 1 : extrait d’un rapport","source":"Texte écrit pour l’exercice","blocs":["Dans la ville imaginaire de Val-Clair, l’observatoire de santé constate en 2023 qu’un habitant sur cinq sans complémentaire santé a renoncé à des soins au cours des douze derniers mois, pour des raisons financières. Il recommande de mieux faire connaître la complémentaire santé solidaire et le tiers payant."]},{"id":"doc2","type":"graphique","forme":"barres","titre":"Document 2 : renoncement aux soins selon la couverture","source":"Chiffres imaginés pour l’exercice.","categories":["Sans complémentaire","Avec complémentaire","Avec C2S"],"series":[{"nom":"Renoncement","valeurs":[20,5,4]}],"axeY":{"titre":"Personnes ayant renoncé","unite":"en %","min":0,"max":25,"pas":5},"axeX":{"titre":"Couverture"}}],"questions":[{"enonce":"Touche le groupe où le renoncement aux soins est le plus fréquent.","aide":"Cherche la barre la plus haute.","type":"zone","document":"doc2","multiple":false},{"enonce":"Les personnes sans complémentaire renoncent combien de fois plus souvent que celles qui en ont une ?","aide":"Divise la valeur la plus haute par celle du groupe « Avec complémentaire ».","type":"nombre","unite":"fois"},{"enonce":"Range chaque phrase d’un paragraphe argumenté : idée, preuve tirée du dossier, ou connaissance personnelle.","aide":"Une preuve cite un document ; une connaissance vient du cours.","type":"categories","categories":[{"id":"c0","texte":"Idée"},{"id":"c1","texte":"Preuve du dossier"},{"id":"c2","texte":"Connaissance personnelle"}],"items":[{"id":"i0","texte":"Les dispositifs financiers réduisent les inégalités d’accès aux soins"},{"id":"i1","texte":"Selon le document 1, un habitant sur cinq sans complémentaire renonce aux soins"},{"id":"i2","texte":"Le coût des soins peut empêcher de se soigner"},{"id":"i3","texte":"Le tiers payant dispense d’avancer les frais chez le professionnel de santé"},{"id":"i4","texte":"Selon le document 2, 5 % des personnes avec complémentaire renoncent aux soins"},{"id":"i5","texte":"La C2S couvre la part complémentaire des soins des ménages modestes"}]},{"enonce":"Quel est l’écart, en points, entre le renoncement des personnes sans complémentaire et celui des personnes avec la C2S ?","aide":"Soustrais les deux pourcentages lus sur le graphique.","type":"nombre","unite":"points"},{"enonce":"Sujet : « Montrer que le coût des soins influence l’accès aux soins. » Quel plan est le meilleur ?","aide":"Un plan classe par idées, pas par documents.","type":"choix","options":[{"id":"a","texte":"I. Ce que dit le document 1 sur le renoncement — II. Ce que dit le document 2 sur les groupes"},{"id":"b","texte":"I. Le coût, un obstacle à l’accès aux soins — II. Des dispositifs qui réduisent cet obstacle"},{"id":"c","texte":"I. Les chiffres donnés par le graphique — II. Les phrases données par le texte du rapport"},{"id":"d","texte":"I. L’organisation des médecins de la région — II. L’organisation des hôpitaux de la région"}],"multiple":false}]}$ex$::jsonb,
