mmune"},{"id":"i3","texte":"Programme régional d’accès à la prévention et aux soins des plus démunis"},{"id":"i4","texte":"Stratégie nationale de santé"},{"id":"i5","texte":"Numéro national de prévention du suicide 3114"}]},{"enonce":"Pourquoi commence-t-on la présentation d’une politique par son contexte ?","aide":"Une politique répond à un problème.","type":"choix","options":[{"id":"a","texte":"Parce que les lois de santé sont toujours votées avant que le problème apparaisse"},{"id":"b","texte":"Parce que le contexte sert surtout à citer tous les textes juridiques en vigueur"},{"id":"c","texte":"Parce qu’une priorité se justifie par un problème de santé repéré grâce aux données"},{"id":"d","texte":"Parce que la présentation doit suivre l’ordre alphabétique des institutions citées"}],"multiple":false}]}$ex$::jsonb,
