   $ex${"titre":"Les usagers entrent dans la décision","competence":"se-reperer-temps","situation":"La démocratie sanitaire s’est construite par étapes depuis les années 1990. Une frise en donne quatre ; tu dois aussi connaître les instances à chaque échelon.","documents":[{"id":"frise","type":"frise","titre":"Quatre étapes de la démocratie sanitaire","source":"Dates des textes et événements officiels.","debut":1990,"fin":2020,"pas":5,"evenements":[{"id":"z1","date":1996,"nom":"Usagers au conseil"},{"id":"z2","date":1998,"nom":"États généraux"},{"id":"z3","date":2002,"nom":"Loi du 4 mars"},{"id":"z4","date":2016,"nom":"France Assos Santé"}]}],"questions":[{"enonce":"Touche l’étape où les représentants des usagers entrent dans les conseils d’administration des hôpitaux.","aide":"C’est la plus ancienne des quatre.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’arrivée des usagers dans les hôpitaux de la création de France Assos Santé ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque instance à son échelon.","aide":"Du plus large au plus proche.","type":"association","gauche":[{"id":"g0","texte":"Conférence nationale de santé"},{"id":"g1","texte":"Conférence régionale de la santé et de l’autonomie"},{"id":"g2","texte":"Conseil territorial de santé"},{"id":"g3","texte":"Commission des usagers"}],"droite":[{"id":"d0","texte":"Territorial"},{"id":"d1","texte":"Établissement"},{"id":"d2","texte":"National"},{"id":"d3","texte":"Régional"}]}]}$ex$::jsonb,
