  ('48936332-692c-52f1-8742-4f9d0794adce'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une réclamation à l’hôpital","competence":"analyser-texte","situation":"M. Bernard est opéré dans un hôpital imaginaire. Certains de ses droits sont respectés, d’autres non. Lis son histoire puis analyse-la.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"L’histoire de M. Bernard","source":"Texte écrit pour l’exercice","blocs":["Lundi, M. Bernard, 71 ans, est opéré de la hanche dans un hôpital de Saint-Rivage, ville imaginaire. La veille, le chirurgien lui a expliqué l’intervention et ses risques, puis lui a proposé une autre solution ; M. Bernard a accepté l’opération librement.","Le lendemain, il demande à lire son dossier médical : on le lui remet sans difficulté.","À sa sortie, l’infirmier évoque sa maladie à voix haute dans le couloir, devant d’autres patients. Personne ne lui a jamais proposé de désigner une personne de confiance. M. Bernard dépose une réclamation auprès de l’hôpital."]}],"questions":[{"enonce":"Touche le mot qui désigne le document que M. Bernard a pu consulter.","aide":"C’est un document médical.","type":"zone","document":"recit","multiple":false},{"enonce":"Range chaque fait selon que le droit du patient est respecté ou non.","aide":"Repère information, consentement, secret médical, personne de confiance.","type":"categories","categories":[{"id":"c0","texte":"Droit respecté"},{"id":"c1","texte":"Droit non respecté"}],"items":[{"id":"i0","texte":"Personne ne propose à M. Bernard de désigner une personne de confiance"},{"id":"i1","texte":"L’infirmier parle de la maladie devant d’autres patients"},{"id":"i2","texte":"Le chirurgien explique l’opération et ses risques ; M. Bernard accepte librement"},{"id":"i3","texte":"M. Bernard obtient son dossier médical quand il le demande"}]},{"enonce":"Que peut faire la commission des usagers après examen de la réclamation ?","aide":"Son rôle est d’examiner et de proposer.","type":"choix","options":[{"id":"a","texte":"Modifier le projet régional de santé de toute la région pour éviter ce type de cas"},{"id":"b","texte":"Voter la loi de financement de la Sécurité sociale en tenant compte de la réclamation"},{"id":"c","texte":"Décider seule de sanctionner l’infirmier en le licenciant de l’hôpital sans délai"},{"id":"d","texte":"Proposer des améliorations, par exemple sur l’accueil et le respect de la confidentialité"}],"multiple":false},{"enonce":"Associe chaque droit à sa définition.","aide":"Chaque droit protège le patient autrement.","type":"association","gauche":[{"id":"g0","texte":"Consentement libre et éclairé"},{"id":"g1","texte":"Personne de confiance"},{"id":"g2","texte":"Directives anticipées"},{"id":"g3","texte":"Secret médical"}],"droite":[{"id":"d0","texte":"Quelqu’un qui parle pour moi si je ne peux plus m’exprimer"},{"id":"d1","texte":"Accepter ou refuser un soin après avoir été informé"},{"id":"d2","texte":"Interdiction de révéler mes informations de santé"},{"id":"d3","texte":"Mes volontés écrites sur ma fin de vie"}]}]}$ex$::jsonb,
