   $ex${"titre":"Un avis qui ne s’impose pas","competence":"argumenter","situation":"Dans une région imaginaire, une agence veut fermer une maternité. L’instance de démocratie sanitaire s’y oppose, mais la décision tombe quand même. Deux documents aident à comprendre.","documents":[{"id":"art","type":"texte","genre":"article","titre":"Un avis défavorable","source":"Article imaginé pour l’exercice","blocs":["L’agence régionale de santé d’Hauterive, région imaginaire, prévoit de fermer la maternité d’un petit hôpital. La conférence régionale de la santé et de l’autonomie rend un avis défavorable, mais l’agence maintient sa décision."]},{"id":"crsa","type":"tableau","titre":"Composition imaginaire de la conférence régionale","source":"Chiffres imaginés pour l’exercice.","colonnes":["Collège","Sièges"],"enteteLignes":true,"lignes":[["Représentants des usagers",12],["Professionnels et établissements",18],["Élus et collectivités",10],["Autres (organismes sociaux, personnalités)",10]]}],"questions":[{"enonce":"Touche le collège qui compte le plus de sièges.","aide":"Cherche le plus grand nombre de sièges.","type":"zone","document":"crsa","multiple":false},{"enonce":"Quelle part des sièges les représentants des usagers détiennent-ils, en % ?","aide":"Divise 12 par le total des sièges.","type":"nombre","unite":"%"},{"enonce":"L’agence peut-elle maintenir sa décision malgré l’avis défavorable ?","aide":"Regarde si l’instance décide ou seulement conseille.","type":"choix","options":[{"id":"a","texte":"Oui : cette instance n’existe pas dans la loi et ses avis sont sans valeur"},{"id":"b","texte":"Oui : cette instance est consultative, son avis ne s’impose pas à l’agence"},{"id":"c","texte":"Non : une telle décision ne peut être prise qu’avec l’accord des usagers"},{"id":"d","texte":"Non : l’avis de la conférence régionale s’impose toujours au directeur de l’agence"}],"multiple":false},{"enonce":"Range chaque élément : atout ou limite de la démocratie sanitaire.","aide":"Les atouts améliorent les décisions, les limites freinent la participation.","type":"categories","categories":[{"id":"c0","texte":"Atout"},{"id":"c1","texte":"Limite"}],"items":[{"id":"i0","texte":"Des représentants peu nombreux et peu connus"},{"id":"i1","texte":"Des avis qui ne s’imposent pas"},{"id":"i2","texte":"Peu de participation des publics éloignés du système de santé"},{"id":"i3","texte":"Des décisions mieux adaptées aux besoins"},{"id":"i4","texte":"Des décisions mieux acceptées"},{"id":"i5","texte":"Le patient devient acteur de sa santé"}]}]}$ex$::jsonb,
