   $ex${"titre":"Un canton sans médecin","competence":"lire-graphique","situation":"Quatre territoires d’un même département n’ont pas le même accès à un médecin généraliste. Un graphique donne la densité de médecins, un tableau la population.","documents":[{"id":"dens","type":"graphique","forme":"barres","titre":"Médecins généralistes pour 10 000 habitants","source":"Données imaginées pour l’exercice.","categories":["Littoral","Plaine","Vallée","Haut-pays"],"series":[{"nom":"Densité","valeurs":[9,7,5,3]}],"axeY":{"titre":"Médecins","unite":"pour 10 000 habitants","min":0,"max":10,"pas":2},"axeX":{"titre":"Territoire"},"valeurs":false},{"id":"pop","type":"tableau","titre":"Population des territoires","source":"Données imaginées pour l’exercice.","colonnes":["Territoire","Habitants"],"enteteLignes":true,"lignes":[["Littoral","30 000"],["Plaine","40 000"],["Vallée","25 000"],["Haut-pays","20 000"]]}],"questions":[{"enonce":"Touche le territoire le plus exposé au risque de désert médical.","aide":"Cherche la barre la plus basse.","type":"zone","document":"dens","multiple":false},{"enonce":"Combien de médecins généralistes exercent dans le Haut-pays ?","aide":"Le Haut-pays compte 20 000 habitants, soit deux fois 10 000.","type":"nombre","unite":"médecins"},{"enonce":"Combien de généralistes de plus faudrait-il au Haut-pays pour atteindre la densité de la Plaine ?","aide":"Calcule d’abord combien la Plaine aurait de médecins pour 20 000 habitants.","type":"nombre","unite":"médecins"},{"enonce":"Quelle mesure agit directement sur cette inégalité de répartition ?","aide":"Il faut inciter des médecins à s’installer là où il en manque.","type":"choix","options":[{"id":"a","texte":"Des aides à l’installation pour les médecins en zone sous-dense"},{"id":"b","texte":"Une hausse du ticket modérateur pour les patients du littoral"},{"id":"c","texte":"La fermeture des centres de santé pour réduire les dépenses"},{"id":"d","texte":"La suppression du tiers payant pour toutes les consultations"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Le **Haut-pays** a la densité la plus faible : 3 généralistes pour 10 000 habitants."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 médecins","explication":"20 000 habitants = 2 × 10 000, donc 2 × 3 = **6 médecins**."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 médecins","explication":"Avec la densité de la Plaine, le Haut-pays aurait 2 × 7 = 14 médecins. Il en a 6 : il en manque **8**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les **aides à l’installation en zone sous-dense** visent à mieux répartir l’offre de soins. Les autres mesures ne changent pas la répartition des médecins."}]$ex$::jsonb),
  ('64ab8cb9-6149-53aa-b70e-8aaee7bd07f8'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"De la chute au retour chez soi","competence":"analyser-document","situation":"Un samedi à 23 h, Mme Roux, 82 ans, chute chez elle. Un tableau présente les établissements du secteur, un récit raconte son histoire.","documents":[{"id":"etab","type":"tableau","titre":"Les établissements autour de Valmont","source":"Établissements imaginés pour l’exercice.","colonnes":["Établissement","Gestion","Ce qu’il propose"],"enteteLignes":true,"lignes":[["Centre hospitalier de Valmont","Hôpital public, regroupé avec d’autres hôpitaux publics du territoire","Urgences ouvertes 24 h sur 24, chirurgie"],["Clinique du Parc","Société privée qui cherche à dégager un bénéfice","Chirurgie programmée"],["Centre Saint-Élie","Association sans but lucratif, qui participe au service public","Rééducation après une hospitalisation"],["CHU de la métropole","Hôpital public","Soins, enseignement et recherche, cas complexes"]]},{"id":"cas","type":"texte","genre":"recit","titre":"L’histoire de Mme Roux","auteur":"Texte écrit pour l’exercice","blocs":["Samedi, à 23 h, Mme Roux chute dans son salon et ne peut plus se relever. À 82 ans, elle est exposée au risque de fracture. Son fils appelle le 15.","Au centre hospitalier de Valmont, qui dispose de 12 lits de chirurgie orthopédique, elle est opérée. Trois semaines de rééducation plus tard, elle rentre chez elle avec le passage d’une infirmière libérale."]}],"questions":[{"enonce":"Mme Roux chute à 23 h. Touche la case qui explique qu’elle puisse être accueillie à cette heure au centre hospitalier.","aide":"Regarde la colonne « Ce qu’il propose » de la première ligne.","type":"zone","document":"etab","multiple":false},{"enonce":"Associe chaque établissement à son statut.","aide":"Lis la colonne « Gestion » : qui gère, et avec quel but ?","type":"association","gauche":[{"id":"g0","texte":"Centre hospitalier de Valmont"},{"id":"g1","texte":"Clinique du Parc"},{"id":"g2","texte":"Centre Saint-Élie"}],"droite":[{"id":"d0","texte":"Établissement public"},{"id":"d1","texte":"ESPIC, privé à but non lucratif"},{"id":"d2","texte":"Privé à but lucratif"}]},{"enonce":"Un groupement hospitalier de territoire réunit des hôpitaux publics. Quels établissements du tableau pourraient en faire partie ensemble ?","aide":"Un GHT ne rassemble que des établissements publics.","type":"choix","options":[{"id":"a","texte":"Le CHU de la métropole et la clinique du Parc"},{"id":"b","texte":"Le centre Saint-Élie et le centre hospitalier de Valmont"},{"id":"c","texte":"La clinique du Parc et le centre Saint-Élie"},{"id":"d","texte":"Le centre hospitalier de Valmont et le CHU de la métropole"}],"multiple":false},{"enonce":"Range chaque phrase : besoin, demande ou offre ?","aide":"Besoin = établi par les professionnels ; demande = exprimée ; offre = disponible.","type":"categories","categories":[{"id":"c0","texte":"Besoin"},{"id":"c1","texte":"Demande"},{"id":"c2","texte":"Offre"}],"items":[{"id":"i0","texte":"À 82 ans, Mme Roux est exposée au risque de fracture"},{"id":"i1","texte":"Le centre Saint-Élie propose de la rééducation"},{"id":"i2","texte":"Son fils appelle le 15 pour obtenir de l’aide"},{"id":"i3","texte":"La famille réclame un retour à domicile rapide"},{"id":"i4","texte":"L’âge avancé de la population du secteur augmente les risques de chute"},{"id":"i5","texte":"Le centre hospitalier dispose de 12 lits de chirurgie orthopédique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"L’hôpital public accueille tout le monde **24 h sur 24** : ses urgences sont ouvertes la nuit."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Le centre hospitalier est **public**, la clinique est **privée à but lucratif**, le centre Saint-Élie est un **ESPIC** : privé à but non lucratif, il participe au service public."},{"cle":{"type":"choix","ids":["d"]},"explication":"Seuls **le centre hospitalier et le CHU**, tous deux publics, peuvent partager un projet médical dans un GHT. La clinique et l’ESPIC sont privés."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c1","i4":"c0","i5":"c2"}},"explication":"Le **besoin** est repéré par les professionnels, la **demande** est exprimée par les personnes, l’**offre** est ce qui existe déjà sur le territoire."}]$ex$::jsonb),
  ('116fa56e-3178-53ed-8f89-088c7cc6b529'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le rendez-vous de Nour","competence":"analyser-document","situation":"Nour, 17 ans, a mal à l’oreille. Elle en discute avec sa mère, qui connaît les règles du parcours de soins.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages de Nour","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Nour","emoji":"👧","cote":"gauche"},{"nom":"Maman","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Nour","texte":"J’ai mal à l’oreille depuis trois jours."},{"qui":"Maman","texte":"Appelle d’abord ton médecin traitant pour avoir un rendez-vous."},{"qui":"Nour","texte":"Et si je vais directement chez un spécialiste de l’oreille ?"},{"qui":"Maman","texte":"Sans passer par lui, tu serais moins bien remboursée."},{"qui":"Nour","texte":"Et pour mes règles douloureuses ?"},{"qui":"Maman","texte":"Là, tu peux voir directement une gynécologue : c’est un accès direct."}]}],"questions":[{"enonce":"Touche les deux mots qui désignent le professionnel qui coordonne le parcours de soins de Nour.","aide":"Il suit la patiente, l’oriente et tient son dossier à jour.","type":"zone","document":"sms","multiple":true},{"enonce":"Touche le spécialiste que Nour peut consulter sans passer par son médecin traitant.","aide":"Un seul spécialiste de la conversation est en accès direct.","type":"zone","document":"sms","multiple":false},{"enonce":"Un spécialiste a un tarif de base de 50 € (chiffre simplifié). De combien d’euros le remboursement baisse-t-il quand Nour consulte hors du parcours de soins ? On ignore les forfaits.","aide":"Dans le parcours, l’assurance maladie rembourse 70 % du tarif de base ; hors parcours, 30 %.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m14"]},"explication":"Le **médecin traitant** coordonne le parcours de soins : il suit le patient et l’oriente vers les spécialistes."},{"cle":{"type":"zone","ids":["m50"]},"explication":"La **gynécologue** fait partie des spécialistes en accès direct, avec l’ophtalmologue, le dentiste et, jusqu’à 25 ans, le psychiatre."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 €","explication":"Dans le parcours : 70 % de 50 € = 35 €. Hors parcours : 30 % de 50 € = 15 €. Le remboursement baisse de **20 €**."}]$ex$::jsonb),
  ('116fa56e-3178-53ed-8f89-088c7cc6b529'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le 15, le 116 117 ou lundi matin ?","competence":"analyser-document","situation":"Le samedi soir, les cabinets sont fermés. Un tableau rappelle qui appeler ; à toi de trier les situations.","documents":[{"id":"numeros","type":"tableau","titre":"Qui appeler ?","colonnes":["Service","Numéro","Pour quoi faire"],"enteteLignes":true,"lignes":[["SAMU","15","Urgences vitales ; régulation médicale à toute heure"],["Médecin de garde","116 117","Soins non programmés quand les cabinets sont fermés ; régulation par téléphone"],["Cabinet du médecin traitant","—","Consultations aux heures d’ouverture, du lundi au vendredi"]]}],"questions":[{"enonce":"Un adulte ressent une douleur violente dans la poitrine, avec des sueurs. Touche le numéro à composer.","aide":"Il s’agit d’une urgence vitale.","type":"zone","document":"numeros","multiple":false},{"enonce":"Samedi, 22 h. Range chaque situation selon la bonne réponse.","aide":"Demande-toi : la vie est-elle en danger ? Sinon, faut-il un avis rapide ou peut-on attendre ?","type":"categories","categories":[{"id":"c0","texte":"Urgence vitale : le 15"},{"id":"c1","texte":"Soin non programmé : régulation"},{"id":"c2","texte":"Sans urgence : attendre l’ouverture"}],"items":[{"id":"i0","texte":"Rhume sans fièvre depuis deux jours"},{"id":"i1","texte":"Douleur violente dans la poitrine avec malaise"},{"id":"i2","texte":"Enfant fiévreux qui joue encore mais inquiète ses parents"},{"id":"i3","texte":"Renouvellement d’une ordonnance de vitamines"},{"id":"i4","texte":"Mal de dos aigu que les antidouleurs n’apaisent pas"},{"id":"i5","texte":"Personne inconsciente qui ne respire plus"}]},{"enonce":"Pourquoi appelle-t-on avant d’aller voir le médecin de garde ?","aide":"Regarde ce que le tableau dit de la régulation par téléphone.","type":"choix","options":[{"id":"a","texte":"Parce que le médecin de garde ne reçoit jamais les patients en personne"},{"id":"b","texte":"Pour payer la consultation à l’avance et obtenir un meilleur remboursement"},{"id":"c","texte":"La régulation oriente vers la bonne réponse : conseil, garde, urgences ou ambulance"},{"id":"d","texte":"Pour que le médecin traitant soit prévenu et signe l’ordonnance à distance"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Une douleur thoracique avec malaise est une **urgence vitale** : on appelle le **15**, le numéro du SAMU."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1","i3":"c2","i4":"c1","i5":"c0"}},"explication":"Les **urgences vitales** relèvent du 15. Les soins non programmés passent par la **régulation** (15 ou 116 117) qui oriente. Le reste peut **attendre l’ouverture** du cabinet."},{"cle":{"type":"choix","ids":["c"]},"explication":"La **régulation** téléphonique évalue la situation et oriente : conseil, médecin de garde, urgences ou ambulance. Elle évite d’engorger les urgences."}]$ex$::jsonb),
  ('116fa56e-3178-53ed-8f89-088c7cc6b529'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le parcours de Mme Diallo","competence":"analyser-document","situation":"Mme Diallo, 58 ans, apprend qu’elle a un diabète de type 2. Son carnet de bord raconte sa prise en charge ; un tableau rappelle les outils de la coordination.","documents":[{"id":"carnet","type":"texte","genre":"recit","titre":"Le carnet de Mme Diallo","auteur":"Texte écrit pour l’exercice","blocs":["Mon médecin traitant établit le protocole de soins qui ouvre mon affection de longue durée : les soins liés au diabète seront pris en charge à 100 % du tarif de base.","Je suis un atelier où j’apprends à surveiller ma glycémie, à adapter mon alimentation et à reconnaître les signes d’alerte.","Mes résultats d’analyses et mes ordonnances sont rangés dans mon espace numérique, où j’échange par messagerie sécurisée avec mes soignants.","Une assistante sociale m’aide aussi à aménager mes horaires avec mon employeur et à reprendre une activité physique."]},{"id":"outils","type":"tableau","titre":"Les outils de la coordination","colonnes":["Outil","Son rôle"],"enteteLignes":true,"lignes":[["Mon espace santé","Espace numérique personnel : dossier médical partagé et messagerie sécurisée"],["Protocole de soins en ALD","Plan de soins établi par le médecin traitant, pris en charge à 100 %"],["Dispositif d’appui à la coordination","Aide les professionnels face aux situations complexes"],["Éducation thérapeutique du patient","Rend le malade chronique autonome dans la gestion de sa maladie"]]}],"questions":[{"enonce":"Associe chaque passage du carnet à l’outil qu’il illustre.","aide":"Cherche, dans le tableau, le rôle qui correspond à chaque passage.","type":"association","gauche":[{"id":"g0","texte":"Les soins du diabète sont pris en charge à 100 %"},{"id":"g1","texte":"J’apprends à surveiller ma glycémie"},{"id":"g2","texte":"J’échange par messagerie sécurisée avec mes soignants"}],"droite":[{"id":"d0","texte":"Mon espace santé"},{"id":"d1","texte":"Protocole de soins en ALD"},{"id":"d2","texte":"Éducation thérapeutique du patient"}]},{"enonce":"Touche le mot qui montre que le parcours de Mme Diallo dépasse le soin et touche sa vie professionnelle.","aide":"Cherche, dans le dernier paragraphe, la personne avec qui elle aménage ses horaires.","type":"zone","document":"carnet","multiple":false},{"enonce":"Le même jour, Mme Diallo paie deux soins au tarif de base : une prise de sang pour son diabète (20 €) et une consultation pour une angine (30 €, dans le parcours de soins). Combien l’assurance maladie rembourse-t-elle en tout ? On ignore les forfaits.","aide":"Les soins liés à l’ALD sont à 100 % ; la consultation dans le parcours est remboursée à 70 %.","type":"nombre","unite":"€"},{"enonce":"Mme Diallo choisit avec son médecin entre deux traitements, après une explication claire. Quelle place la personne occupe-t-elle ?","aide":"Pense à la décision médicale partagée.","type":"choix","options":[{"id":"a","texte":"Elle est usagère-actrice : informée, elle prend part à la décision médicale partagée"},{"id":"b","texte":"Elle est écartée du parcours, que les professionnels organisent entre eux seuls"},{"id":"c","texte":"Elle est remplacée par une association qui décide à sa place pour les usagers"},{"id":"d","texte":"Elle est patiente passive : le médecin choisit seul puis l’informe de sa décision"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Le **protocole de soins** ouvre la prise en charge à 100 %, l’**éducation thérapeutique** rend autonome, **Mon espace santé** réunit le dossier médical partagé et la messagerie."},{"cle":{"type":"zone","ids":["m86"]},"explication":"Aménager ses horaires avec son **employeur** relève du parcours de **vie** : il englobe le travail, le logement et la vie sociale."},{"cle":{"type":"nombre","valeur":41,"tolerance":0},"affichage":"41 €","explication":"Prise de sang : 100 % de 20 € = 20 €. Consultation : 70 % de 30 € = 21 €. Total : **41 €**."},{"cle":{"type":"choix","ids":["a"]},"explication":"La personne est **usagère-actrice** : informée, elle consent, choisit et participe aux décisions qui la concernent."}]$ex$::jsonb),
  ('f2143bb3-3acd-5197-94e3-f7faaba041c3'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Combien reste-t-il à payer ?","competence":"calculer","situation":"Lina va chez un spécialiste du parcours de soins : la consultation est facturée 50 € au tarif de base. Un schéma suit le chemin de la dépense.","documents":[{"id":"chemin","type":"chaine","titre":"Le chemin d’une dépense de santé","disposition":"colonne","noeuds":[{"id":"z1","texte":"Le soin : consultation à 50 €"},{"id":"z2","texte":"Tarif de base : 50 €"},{"id":"z3","texte":"Assurance maladie obligatoire : 70 %"},{"id":"z4","texte":"Complémentaire santé, si elle existe"},{"id":"z5","texte":"Reste à charge du patient"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Lina n’a pas de complémentaire santé. Touche l’étape où elle paie elle-même ce qui n’est pas remboursé.","aide":"C’est la dernière étape du schéma.","type":"zone","document":"chemin","multiple":false},{"enonce":"Combien l’assurance maladie obligatoire rembourse-t-elle à Lina ?","aide":"Applique le taux du schéma au tarif de base.","type":"nombre","unite":"€"},{"enonce":"Sans complémentaire, combien Lina doit-elle payer elle-même ? On ignore les forfaits.","aide":"Soustrais le remboursement du tarif de base.","type":"nombre","unite":"€"},{"enonce":"Complète la conclusion.","aide":"Le ticket est la part qui reste après le remboursement.","type":"trous","segments":["L’assurance maladie rembourse une part du ",0," de base ; la complémentaire santé peut prendre en charge le ticket ",1," ."],"banque":["hospitalier","modérateur","tarif","forfait","prix"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"Ce qui n’est remboursé par personne reste à la charge du patient : le **reste à charge**."},{"cle":{"type":"nombre","valeur":35,"tolerance":0},"affichage":"35 €","explication":"70 % de 50 € = **35 €**."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 €","explication":"50 € − 35 € = **15 €** : c’est le ticket modérateur."},{"cle":{"type":"trous","trous":[["tarif"],["moderateur"]]},"affichage":"tarif · modérateur","explication":"Le remboursement porte sur le **tarif** de base ; la part qui reste est le ticket **modérateur**, que la complémentaire peut couvrir."}]$ex$::jsonb),
