   $ex${"titre":"Quatre raisons de ne pas se soigner","competence":"analyser-document","situation":"Quatre personnes expliquent pourquoi elles ont retardé ou abandonné un soin. Un second tableau mesure un autre frein : le non-recours.","documents":[{"id":"temoins","type":"tableau","titre":"Quatre témoignages","source":"Témoignages imaginés pour l’exercice.","colonnes":["Personne","Ce qu’elle raconte"],"enteteLignes":true,"lignes":[["Samia, 29 ans","Le cabinet le plus proche est à 45 km et le prochain rendez-vous est dans deux mois."],["Karim, 52 ans","Mes lunettes coûtent plus que ce que je peux payer, et je n’ai pas de mutuelle."],["Élodie, 34 ans","Je ne savais pas que j’avais droit à une aide, et les formulaires m’ont découragée."],["Yusuf, 67 ans","Je ne comprends pas bien les explications du médecin et je n’ose pas redemander."]]},{"id":"c2s","type":"tableau","titre":"Complémentaire santé solidaire dans un département","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Nombre de foyers"],"enteteLignes":true,"lignes":[["Foyers qui ont droit à la C2S",400],["Foyers qui l’ont demandée",260]]}],"questions":[{"enonce":"Touche le témoignage qui illustre le non-recours : un droit existe, mais on ne l’utilise pas.","aide":"Cherche la personne qui ne connaissait pas son droit.","type":"zone","document":"temoins","multiple":false},{"enonce":"Range chaque personne selon l’obstacle principal à l’accès aux soins.","aide":"Distance, argent, démarches, compréhension : quel obstacle chacun évoque-t-il ?","type":"categories","categories":[{"id":"c0","texte":"Financier"},{"id":"c1","texte":"Géographique"},{"id":"c2","texte":"Administratif"},{"id":"c3","texte":"Culturel et social"}],"items":[{"id":"i0","texte":"Karim"},{"id":"i1","texte":"Élodie"},{"id":"i2","texte":"Yusuf"},{"id":"i3","texte":"Samia"}]},{"enonce":"Quelle part des foyers qui ont droit à la C2S ne l’ont pas demandée ?","aide":"Calcule d’abord combien de foyers ne l’ont pas demandée.","type":"nombre","unite":"%"},{"enonce":"Quelle aide répond le mieux à la situation de Karim ?","aide":"Son frein est financier : il lui manque une complémentaire.","type":"choix","options":[{"id":"a","texte":"Une aide à l’installation d’un médecin près de son domicile"},{"id":"b","texte":"Un protocole de soins qui le place en affection de longue durée"},{"id":"c","texte":"L’aide médicale de l’État, réservée aux étrangers en situation irrégulière"},{"id":"d","texte":"La complémentaire santé solidaire, si ses ressources sont assez modestes"}],"multiple":false}]}$ex$::jsonb,
