   $ex${"titre":"Trois façons d’aider","competence":"analyser-document","situation":"Aider les plus fragiles a pris des formes très différentes au fil de l’histoire. Un tableau décrit trois situations d’aide.","documents":[{"id":"situations","type":"tableau","titre":"Trois situations d’aide","source":"Situations imaginées pour l’exercice.","colonnes":["Situation","Ce qui se passe"],"enteteLignes":true,"lignes":[["A","Une dame de la paroisse distribue du pain aux pauvres qu’elle choisit, selon son bon vouloir."],["B","Un ouvrier malade est indemnisé grâce aux cotisations prélevées sur les salaires."],["C","Une mère seule reçoit le RSA, financé par l’impôt, avec un accompagnement vers l’emploi."]]}],"questions":[{"enonce":"Touche la situation où l’aide ouvre un droit grâce à des cotisations.","aide":"Cherche l’aide qui dépend de ce qu’on a versé grâce à son travail.","type":"zone","document":"situations","multiple":false},{"enonce":"Range chaque élément selon la logique dont il relève.","aide":"Charité : bon vouloir. Assurance : cotisations. Solidarité : impôt et accompagnement.","type":"categories","categories":[{"id":"c0","texte":"Charité, assistance"},{"id":"c1","texte":"Assurance"},{"id":"c2","texte":"Solidarité nationale, insertion"}],"items":[{"id":"i0","texte":"Sécurité sociale de 1945"},{"id":"i1","texte":"Bureaux de bienfaisance"},{"id":"i2","texte":"Situation A"},{"id":"i3","texte":"Revenu de solidarité active"},{"id":"i4","texte":"Situation C"},{"id":"i5","texte":"Situation B"}]},{"enonce":"Pourquoi la situation C ne relève-t-elle pas de la logique d’assurance ?","aide":"Relis ce que dit le tableau du financement de la situation C.","type":"choix","options":[{"id":"a","texte":"La personne n’a droit à aucun accompagnement, seulement à une somme"},{"id":"b","texte":"Les droits ne dépendent pas de cotisations : l’aide est financée par l’impôt"},{"id":"c","texte":"L’aide dépend du bon vouloir d’une bienfaitrice qui choisit ses pauvres"},{"id":"d","texte":"La personne ne reçoit aucun argent, seulement des aides en nature"}],"multiple":false}]}$ex$::jsonb,
