  ('1d6a620e-3d0a-5c9c-a042-7e8b942c8481'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Jade, étudiante en fauteuil","competence":"analyser-texte","situation":"Jade, 28 ans, étudie le droit et se déplace en fauteuil. Son histoire montre ce que la loi de 2005 a changé par rapport à celle de 1975.","documents":[{"id":"jade","type":"texte","genre":"recit","titre":"L’histoire de Jade","auteur":"Texte écrit pour l’exercice","blocs":["En 1975, raconte son grand-père, Jade aurait surtout trouvé une place dans un établissement spécialisé.","Aujourd’hui, elle a déposé son dossier à la MDPH de son département, qui lui a ouvert un droit à compensation : une aide financière pour un fauteuil adapté.","À la faculté, une rampe et un ascenseur rendent toutes les salles accessibles. Jade est aussi consultée sur le projet d’accessibilité de l’université."]},{"id":"lois","type":"tableau","titre":"Deux lois, deux logiques","colonnes":["","Loi de 1975","Loi de 2005"],"enteteLignes":true,"lignes":[["Logique","Protection","Citoyenneté"],["Mots-clés","Établissements, allocations","Compensation, accessibilité, participation"]]}],"questions":[{"enonce":"Touche le mot qui désigne la structure créée en 2005 où Jade a déposé sa demande de compensation.","aide":"Ce sigle désigne la maison du handicap de chaque département.","type":"zone","document":"jade","multiple":false},{"enonce":"Associe chaque élément de l’histoire de Jade à la notion qu’il illustre.","aide":"Les trois notions sont dans la dernière ligne du tableau.","type":"association","gauche":[{"id":"g0","texte":"Une aide financière pour un fauteuil adapté"},{"id":"g1","texte":"Une rampe et un ascenseur à la faculté"},{"id":"g2","texte":"Jade consultée sur le projet de l’université"}],"droite":[{"id":"d0","texte":"L’accessibilité"},{"id":"d1","texte":"La participation"},{"id":"d2","texte":"Le droit à compensation"}]},{"enonce":"Range chaque élément : loi de 1975 ou loi de 2005 ?","aide":"Observe le tableau : quelle loi parle de protection, laquelle de citoyenneté ?","type":"categories","categories":[{"id":"c0","texte":"Loi de 1975"},{"id":"c1","texte":"Loi de 2005"}],"items":[{"id":"i0","texte":"Les maisons départementales des personnes handicapées"},{"id":"i1","texte":"La prestation de compensation du handicap"},{"id":"i2","texte":"L’obligation d’accessibilité des lieux"},{"id":"i3","texte":"Une logique de protection"},{"id":"i4","texte":"Des établissements spécialisés et des allocations"},{"id":"i5","texte":"Une allocation pour adultes handicapés instituée par la loi"}]},{"enonce":"Quelle évolution l’histoire de Jade illustre-t-elle entre 1975 et 2005 ?","aide":"Compare les deux colonnes du tableau, ligne « Logique ».","type":"choix","options":[{"id":"a","texte":"D’une logique d’assurance à une logique d’assistance"},{"id":"b","texte":"D’une logique de protection à une logique de citoyenneté"},{"id":"c","texte":"D’une aide locale facultative à une aide uniquement privée"},{"id":"d","texte":"D’une logique de citoyenneté à une logique de protection"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23"]},"explication":"La **MDPH** (maison départementale des personnes handicapées) a été créée par la loi de 2005."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"L’aide financière est la **compensation**, la rampe et l’ascenseur relèvent de l’**accessibilité**, la consultation de Jade relève de la **participation**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c0"}},"explication":"La loi de **1975** organise établissements et allocations, dans une logique de protection. La loi de **2005** crée la compensation, l’accessibilité, la participation et les MDPH."},{"cle":{"type":"choix","ids":["b"]},"explication":"On passe d’une **logique de protection** à une **logique de citoyenneté** : la personne n’est plus prise en charge, elle est accompagnée dans son propre projet."}]$ex$::jsonb),
